+const { spawnSync } = require('node:child_process');
+const fs = require('node:fs');
+const os = require('node:os');
+const path = require('node:path');
+
+require('chai').should();
+
+describe('select_db_host.sh', function () {
+    let tempDir;
+
+    beforeEach(function () {
+        tempDir = fs.mkdtempSync(path.join(os.tmpdir(), 'select-db-host-'));
+    });
+
+    afterEach(function () {
+        fs.rmSync(tempDir, { force: true, recursive: true });
+    });
+
+    function writeExecutable(name, contents) {
+        const filePath = path.join(tempDir, name);
+        fs.writeFileSync(filePath, contents);
+        fs.chmodSync(filePath, 0o755);
+    }
+
+    it('Should avoid awk builtin names while comparing normalized host load', function () {
+        const gawkCheck = spawnSync('gawk', ['--version'], { encoding: 'utf8' });
+        if (gawkCheck.status !== 0) {
+            this.skip();
+        }
+
+        writeExecutable(
+            'awk',
+            ['#!/bin/bash', 'exec gawk --lint "$@"', ''].join('\n'),
+        );
+        writeExecutable(
+            'ssh',
+            [
+                '#!/bin/bash',
+                'target=""',
+                'remote_cmd=""',
+                'for arg in "$@"; do',
+                '  case "$arg" in',
+                '    deploy@*) target="${arg#deploy@}" ;;',
+                '  esac',
+                '  remote_cmd="$arg"',
+                'done',
+                'case "$remote_cmd" in',
+                '  *"/proc/loadavg"*)',
+                '    case "$target" in',
+                '      host-a) echo "8.00" ;;',
+                '      host-b) echo "1.00" ;;',
+                '      *) echo "4.00" ;;',
+                '    esac',
+                '    ;;',
+                '  "nproc")',
+                '    case "$target" in',
+                '      host-a) echo "4" ;;',
+                '      host-b) echo "2" ;;',
+                '      *) echo "1" ;;',
+                '    esac',
+                '    ;;',
+                '  *) exit 1 ;;',
+                'esac',
+                '',
+            ].join('\n'),
+        );
+
+        const scriptPath = path.resolve(
+            __dirname,
+            '../../../scripts/test-db/select_db_host.sh',
+        );
+        const result = spawnSync(scriptPath, ['host-a host-b'], {
+            encoding: 'utf8',
+            env: {
+                ...process.env,
+                PATH: `${tempDir}${path.delimiter}${process.env.PATH}`,
+            },
+        });
+
+        result.status.should.equal(0, result.stderr);
+        result.stdout.trim().should.equal('host-b');
+        result.stderr.should.include('host-a: load=8.00 cpus=4 normalized=2.00');
+        result.stderr.should.include('host-b: load=1.00 cpus=2 normalized=0.50');
+    });
+
+    it('Should fall back to the first host when every host check fails', function () {
+        writeExecutable(
+            'ssh',
+            ['#!/bin/bash', 'exit 1', ''].join('\n'),
+        );
+
+        const scriptPath = path.resolve(
+            __dirname,
+            '../../../scripts/test-db/select_db_host.sh',
+        );
+        const result = spawnSync(scriptPath, ['host-a host-b'], {
+            encoding: 'utf8',
+            env: {
+                ...process.env,
+                PATH: `${tempDir}${path.delimiter}${process.env.PATH}`,
+            },
+        });
+
+        result.status.should.equal(0, result.stderr);
+        result.stdout.trim().should.equal('host-a');
+        result.stderr.should.include('All host checks failed, falling back to host-a');
+    });
+});

